/* GET cbs-crew-me: one saved name for the crew pages. Loaded on the sign-on and load-up crew pages.
   Only acts when the page was opened from the crew portal (?me=1): fills an empty name box with the name saved on this phone
   (cbs_name, the same key the crew portal and task checklists use) and saves a name typed there back to it.
   Hand-round sheets on the site manager's phone (no me=1) are left alone. */
function CREWME(){
var Q=new URLSearchParams(location.search);if(!Q.get('me'))return;
function g(){try{var n=localStorage.getItem('cbs_name')||'';if(!n){var o=JSON.parse(localStorage.getItem('cbs_me')||'null');if(o&&o.name)n=o.name;}return n;}catch(x){return '';}}
function set(n){n=String(n||'').trim();if(!n)return;try{localStorage.setItem('cbs_name',n);var o={};try{o=JSON.parse(localStorage.getItem('cbs_me')||'{}')||{};}catch(x){}o.name=n;localStorage.setItem('cbs_me',JSON.stringify(o));}catch(x){}}
var SEL='input#nm,input[autocomplete="name"],input[name="name"],input[id*="name" i],input[placeholder*="your name" i]';
var done=false;
function fill(){var n=g();[].forEach.call(document.querySelectorAll(SEL),function(i){if(i.__cbsme)return;i.__cbsme=1;
  if(n&&!i.value&&!done){i.value=n;done=true;i.dispatchEvent(new Event('input',{bubbles:true}));i.dispatchEvent(new Event('change',{bubbles:true}));}
  i.addEventListener('change',function(){set(i.value);});});}
fill();new MutationObserver(fill).observe(document.documentElement,{childList:true,subtree:true});
}
return [{json:{js:'('+CREWME.toString()+')();'}}];
